// ================== AUDIO ENGINE (Math Starfighters v4) ==================
// Música orquestal original (renderizada con GeneralUser GS) + efectos. API: AE.init / music / sting / sfx / setMuted / suspend / resume / rate
(function(){
  'use strict';
  const D=window.AE_DATA||{music:{},sfx:{},loops:{}};
  let ac=null,master=null,musicBus=null,sfxBus=null,ready=false,decoding=false,muted=false,rateV=1;
  const buf={};let cur=null,curName=null,want=null,pendingSting=null;
  function b64ToAB(s){const i=s.indexOf(',');const bin=atob(i>=0?s.slice(i+1):s);const u=new Uint8Array(bin.length);for(let k=0;k<bin.length;k++)u[k]=bin.charCodeAt(k);return u.buffer;}
  function decode(ab){return new Promise((res,rej)=>{try{const p=ac.decodeAudioData(ab,res,rej);if(p&&p.then)p.then(res,rej);}catch(e){rej(e);}});}
  async function decodeAll(){
    if(decoding)return;decoding=true;
    const jobs=[];
    // SFX primero (cortos), luego la música pedida, luego el resto
    for(const k in D.sfx)jobs.push(['s:'+k,D.sfx[k]]);
    const order=Object.keys(D.music).sort((a,b)=>(a===want?-1:b===want?1:0));
    for(const k of order)jobs.push(['m:'+k,D.music[k]]);
    for(const [k,data] of jobs){try{buf[k]=await decode(b64ToAB(data));}catch(e){}
      if(k==='m:'+want&&!cur)startMusic(want);
      if(pendingSting&&k==='m:'+pendingSting){const s=pendingSting;pendingSting=null;AE.sting(s);}}
    ready=true;if(want&&curName!==want)startMusic(want);
  }
  function startMusic(name){
    try{
      if(!ac)return;
      const t=ac.currentTime,FADE=0.6;
      if(cur){const old=cur;old.g.gain.cancelScheduledValues(t);old.g.gain.setValueAtTime(old.g.gain.value,t);old.g.gain.linearRampToValueAtTime(0.0001,t+FADE);try{old.src.stop(t+FADE+0.05);}catch(e){}cur=null;curName=null;}
      if(!name)return;
      const b=buf['m:'+name];if(!b)return;
      const src=ac.createBufferSource();src.buffer=b;src.loop=true;
      const L=(D.loops&&D.loops[name])||{off:0,len:b.duration};
      const ls=Math.min(Math.max(0,L.off||0),b.duration-0.1),le=Math.min(b.duration,ls+(L.len||b.duration));
      src.loopStart=ls;src.loopEnd=le;src.playbackRate.value=rateV;
      const g=ac.createGain();g.gain.setValueAtTime(0.0001,t);g.gain.linearRampToValueAtTime(1,t+FADE);
      src.connect(g);g.connect(musicBus);src.start(t,ls);
      cur={src,g};curName=name;
    }catch(e){}
  }
  const AE={
    init(){
      try{
        if(!ac){const C=window.AudioContext||window.webkitAudioContext;if(!C)return;ac=new C();
          master=ac.createGain();master.gain.value=muted?0:1;
          const comp=ac.createDynamicsCompressor();comp.threshold.value=-10;comp.ratio.value=3;
          master.connect(comp);comp.connect(ac.destination);
          musicBus=ac.createGain();musicBus.gain.value=0.75;musicBus.connect(master);
          sfxBus=ac.createGain();sfxBus.gain.value=0.9;sfxBus.connect(master);
          decodeAll();}
        if(ac.state==='suspended')ac.resume().catch(()=>{});
      }catch(e){}
    },
    music(name){try{name=name||null;want=name;if(!ac)return;if(name===curName&&cur)return;if(!name){startMusic(null);return;}if(buf['m:'+name])startMusic(name);}catch(e){}},
    current(){return curName;},
    sting(name){
      try{if(!ac)return;const b=buf['m:'+name];if(!b){pendingSting=name;return;}
        const t=ac.currentTime;musicBus.gain.cancelScheduledValues(t);musicBus.gain.setValueAtTime(musicBus.gain.value,t);
        musicBus.gain.linearRampToValueAtTime(0.15,t+0.25);musicBus.gain.setValueAtTime(0.15,t+b.duration-1.2);musicBus.gain.linearRampToValueAtTime(0.75,t+b.duration+0.5);
        const s=ac.createBufferSource();s.buffer=b;const g=ac.createGain();g.gain.value=1;s.connect(g);g.connect(master);s.start(t);
      }catch(e){}
    },
    sfx(name,vol){try{if(!ac||muted)return;const b=buf['s:'+name];if(!b)return;const s=ac.createBufferSource();s.buffer=b;
      if(name==='laser'||name==='gem')s.playbackRate.value=0.95+Math.random()*0.1;
      const g=ac.createGain();g.gain.value=vol==null?1:vol;s.connect(g);g.connect(sfxBus);s.start();}catch(e){}},
    setMuted(m){muted=!!m;try{if(master)master.gain.setTargetAtTime(muted?0:1,ac.currentTime,0.05);}catch(e){}},
    suspend(){try{if(ac&&ac.state==='running')ac.suspend();}catch(e){}},
    resume(){try{if(ac&&ac.state==='suspended')ac.resume();}catch(e){}},
    rate(r){rateV=Math.max(0.5,Math.min(1.5,r||1));try{if(cur)cur.src.playbackRate.setTargetAtTime(rateV,ac.currentTime,0.3);}catch(e){}},
    isReady(){return ready;},
  };
  window.AE=AE;
})();
